@csrf_exempt
@require_http_methods(["GET"])
def api_availability(request: HttpRequest) -> JsonResponse:
    """Public-shaped, API-key-protected availability endpoint.

    Required query params:
        provider — provider primary key
        type     — appointment type primary key
        day      — ISO date (YYYY-MM-DD), optional; defaults to today.
    """
    key = authenticate_api_key(request)
    if key is None or key.scope != "availability":
        return JsonResponse({"error": "unauthorized"}, status=401)

    try:
        provider_id = int(request.GET.get("provider", ""))
        type_id = int(request.GET.get("type", ""))
    except (TypeError, ValueError):
        return JsonResponse({"error": "provider and type are required integers"}, status=400)

    day_raw = (request.GET.get("day") or "").strip()
    try:
        day = date.fromisoformat(day_raw) if day_raw else timezone.localdate()
    except ValueError:
        return JsonResponse({"error": "day must be ISO date"}, status=400)
    if day < timezone.localdate() or day > timezone.localdate() + timedelta(days=60):
        return JsonResponse({"error": "day must be within 60 days from today"}, status=400)

    provider = Provider.objects.filter(pk=provider_id, is_accepting_new_patients=True).first()
    appt_type = AppointmentType.objects.filter(pk=type_id, is_active=True).first()
    if provider is None or appt_type is None:
        return JsonResponse({"error": "not found"}, status=404)

    slots = get_open_slots(provider, day, duration_minutes=appt_type.duration_minutes)
    log_event(
        request,
        "api.availability.read",
        actor=key.owner,
        target=str(key.pk),
        metadata={"provider": provider_id, "type": type_id, "day": str(day), "slot_count": len(slots)},
    )
    return JsonResponse(
        {
            "provider": {"id": provider.pk, "name": provider.display_name},
            "appointment_type": {"id": appt_type.pk, "name": appt_type.name,
                                 "duration_minutes": appt_type.duration_minutes},
            "day": day.isoformat(),
            "slots": [s.isoformat() for s in slots],
        }
    )

